  b1Ep20BlankHint: "Ein Wort.",
  b1Ep20OpenInstruction: "Stelle eine Nachfrage zu dem, was ich gerade gesagt habe.",
  b1Ep20OpenInstruction2: "Frag auch dazu etwas.",
  b1Ep21Title: "Also im Grunde",
  b1Ep21Goal: "Fasse kurz zusammen, was jemand anderes gesagt hat.",
  b1Ep21CanDoName: "Das Gesagte zusammenfassen",
  b1Ep21Duration: "7 Min.",
  b1Ep21SceneTitle: "Prüfen, ob du verstanden hast",
  b1Ep21SceneBody: "Manchmal hilft es, mit eigenen Worten zu wiederholen, was du gerade gehört hast.",
