  b1RetryPromptTopicEmpty: "Wechsle zu einem anderen Thema.",
  b1PraiseTopicChangeIndependent: "Klasse — das ist ein natürlicher, höflicher Themenwechsel.",
  b1PraiseTopicChangeHelped: "Gut gemacht — das wechselt das Thema klar.",
  b1PraiseTopicFollowIndependent: "Perfekt — du bist ganz natürlich auf das neue Thema eingegangen.",
  b1PraiseTopicFollowHelped: "Gut — das geht auf das neue Thema ein.",
  b1RetryExplainTopicContent: "Guter Marker — füge jetzt hinzu, worüber du eigentlich sprechen möchtest.",
  b1RetryPromptTopicContent: "Sag, was das neue Thema eigentlich ist.",
  b1RetryExplainTopicMarker: "Gutes neues Thema — füge jetzt einen Marker wie „anyway“ oder „by the way“ hinzu.",
  b1RetryPromptTopicMarker: "Füge „anyway“, „by the way“ oder „speaking of“ hinzu.",
  b1RetryExplainTopicRepeat: "Ein echter Themenwechsel sagt etwas Neues — versuch, deine eigene Idee hinzuzufügen.",
  b1RetryPromptTopicRepeat: "Sag etwas anderes als das, was ich gerade gesagt habe.",
  b1RetryPromptTopicFollow: "Sag etwas zum neuen Thema.",
  b1RetryPromptFollowUpEmpty: "Stell mir eine Frage zu dem, was ich gerade gesagt habe.",
  b1PraiseFollowUpIndependent: "Klasse — eine echte Nachfrage.",
  b1PraiseFollowUpHelped: "Gut gemacht — das zeigt echtes Interesse.",
  b1RetryExplainFollowUpForm: "Versuch eine kurze, echte Reaktion, wie „Really?“ oder „Why?“",
  b1RetryPromptFollowUpForm: "Stell eine richtige Nachfrage.",
  b1RetryExplainFollowUpRepeat: "Eine Nachfrage fragt etwas Neues — versuch, nach einem Detail zu fragen.",
  b1RetryPromptFollowUpRepeat: "Frag etwas anderes als das, was ich gerade gesagt habe.",
  b1RetryPromptSummaryEmpty: "Fasse mit eigenen Worten zusammen, was ich dir gerade erzählt habe.",
  b1PraiseSummaryIndependent: "Klasse — eine klare, treffende Zusammenfassung.",
  b1PraiseSummaryHelped: "Gut gemacht — das gibt den Hauptpunkt wieder.",
  b1RetryExplainSummaryContent: "Guter Anfang — füge jetzt noch etwas mehr von dem hinzu, was ich tatsächlich gesagt habe.",
  b1RetryPromptSummaryContent: "Füge deiner Zusammenfassung mehr Details hinzu.",
