  b1Ep22Title: "Das lange Gespräch, Teil eins",
  b1Ep22Goal: "Führe ein echtes Gespräch, das sich durch mehrere Themen bewegt.",
  b1Ep22CanDoName: "Ein langes, sich entwickelndes Gespräch führen",
  b1Ep22Duration: "14 Min.",
  b1Ep22SceneTitle: "Ein Gespräch, von Anfang bis Ende",
  b1Ep22SceneBody: "Diesmal keine neue Grammatik — nur ein langes, echtes Gespräch, in dem du alles nutzt, was du schon kannst.",
